test('invoiceTotals calculates total as subtotal - discount + vat', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 100000;
  const expectedDiscount = 10000;
  const expectedAmountAfterDiscount = 90000;
  const expectedVat = Math.round(expectedAmountAfterDiscount * 0.21);
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVat;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

