  // WORKSHOP-DAY: 2 × 60000 = 120000 cents
  // C-001 is gold tier (5% discount): 120000 * 0.05 = 6000 cents
  // Total: 120000 - 6000 = 114000 cents = €1,140.00
  assert.ok(text.includes('Total: €1,140.00'));
});

